using System.Net;using System.Net.Http;using System.Security.Cryptography;using System.Text;using System.Text.Json;using System.Text.RegularExpressions;using TownOfHost;
partial class Program {
static int wireFailures;
static async Task WireTest(string name,Func<Task> test){try{await Test(name,test);}catch(Exception e){wireFailures++;Console.WriteLine("FAIL "+name+": "+e.GetType().Name);}}
static Dictionary<string,string> DecodeForm(string value)=>value.TrimStart('?').Split('&',StringSplitOptions.RemoveEmptyEntries).Select(x=>x.Split('=',2)).ToDictionary(x=>WebUtility.UrlDecode(x[0]),x=>x.Length==2?WebUtility.UrlDecode(x[1]):"",StringComparer.Ordinal);
sealed class TokenWireHandler:HttpMessageHandler {
 internal Dictionary<string,string> Expected;internal int Calls;internal TokenWireHandler(Dictionary<string,string> expected){Expected=expected;}
 protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){Calls++;Check(request.Method==HttpMethod.Post);Check(request.RequestUri.AbsoluteUri=="https://oauth2.googleapis.com/token");Check(request.Content.Headers.ContentType.MediaType=="application/x-www-form-urlencoded");Check(request.Headers.Authorization==null);var form=DecodeForm(await request.Content.ReadAsStringAsync(token));Check(form.Count==5&&form.Keys.OrderBy(x=>x).SequenceEqual(new[]{"client_id","code","code_verifier","grant_type","redirect_uri"}.OrderBy(x=>x)));foreach(var x in Expected)Check(form.TryGetValue(x.Key,out var v)&&v==x.Value);return new(HttpStatusCode.OK){Content=new StringContent(TokenJson(),Encoding.UTF8,"application/json")};}
}
static YouTubePkceSession Session(string path="/oauth2/callback",int port=12345)=>new(Id,new Uri("http://127.0.0.1:"+port+path));
static Dictionary<string,string> CompleteSynthetic(YouTubePkceSession session,string rawCode="synthetic-code"){var q=DecodeForm(session.AuthorizationUri.Query);return session.Complete(new Uri(session.Redirect+"?state="+Uri.EscapeDataString(q["state"])+"&code="+rawCode));}
static async Task CheckWire(Dictionary<string,string> form){var h=new TokenWireHandler(new(form));using var exchange=new YouTubeDesktopOAuth(new HttpClient(h));Check((await exchange.ExchangeAsync(form,default)).Access.Valid&&h.Calls==1);}
static async Task TokenWireTests(){wireFailures=0;
await WireTest("wire endpoint method content type and exact parameter set",()=>CheckWire(CompleteSynthetic(Session())));
await WireTest("S256 matches submitted verifier with stable session entropy",()=>{var seen=new HashSet<string>();for(int i=0;i<24;i++){var session=Session();var q=DecodeForm(session.AuthorizationUri.Query);Check(q["code_challenge_method"]=="S256");Check(DecodeForm(session.AuthorizationUri.Query)["code_challenge"]==q["code_challenge"]);var form=CompleteSynthetic(session);var verifier=form["code_verifier"];Check(Regex.IsMatch(verifier,@"\A[A-Za-z0-9._~-]{43,128}\z")&&seen.Add(verifier));var expected=Convert.ToBase64String(SHA256.HashData(Encoding.ASCII.GetBytes(verifier))).TrimEnd('=').Replace('+','-').Replace('/','_');Check(q["code_challenge"]==expected&&!expected.Contains('='));}return Task.CompletedTask;});
foreach(var (path,port) in new[]{("/oauth2/callback",12345),("/oauth2/callback/",50123),("/oauth2/with%20space",65534)})await WireTest("redirect URI byte equality across stages "+port,async()=>{var session=Session(path,port);var q=DecodeForm(session.AuthorizationUri.Query);var form=CompleteSynthetic(session);Check(form["redirect_uri"]==q["redirect_uri"]&&form["client_id"]==q["client_id"]&&form["grant_type"]=="authorization_code");await CheckWire(form);});
var cases=new[]{("synthetic%2Fcode","synthetic/code"),("synthetic%2Bcode","synthetic+code"),("synthetic+code","synthetic code"),("synthetic%252Bcode","synthetic%2Bcode"),(Uri.EscapeDataString("模擬_日本語+%"),"模擬_日本語+%"),("synthetic%26code%3Dequal%25","synthetic&code=equal%")};
for(int i=0;i<cases.Length;i++){var (raw,expected)=cases[i];await WireTest("callback and form encode round trip "+i,async()=>{var form=CompleteSynthetic(Session(),raw);Check(form["code"]==expected);await CheckWire(form);});}
foreach(var (parameter,expected) in new[]{("client_secret","ClientSecretRequired"),("client_id","ClientIdRequired"),("code","AuthorizationCodeRequired"),("redirect_uri","RedirectUriRequired"),("grant_type","GrantTypeRequired"),("code_verifier","CodeVerifierRequired")})foreach(var style in new[]{0,1})await WireTest("safe missing parameter classifier "+parameter+" "+style,()=>{var description=style==0?parameter+" is missing.":"Missing required parameter: "+parameter;var json=JsonSerializer.Serialize(new{error="invalid_request",error_description=description});var value=YouTubeOAuthDiagnostic.FromGoogle(json,400);Check(value.Code.ToString()==expected&&value.Stage==YouTubeOAuthStage.TokenExchange&&value.HttpStatus==400);return Task.CompletedTask;});
foreach(var description in new[]{"client_secret is missing. "+PrivateMarker,"Missing required parameter: "+PrivateMarker,PrivateMarker,new string('x',200)+"client_secret is missing.",""})await WireTest("unknown error description remains redacted "+description.Length,()=>{var value=YouTubeOAuthDiagnostic.FromGoogle(JsonSerializer.Serialize(new{error="invalid_request",error_description=description}),400);Check(value.Code==YouTubeOAuthCode.InvalidRequest&&!(value.SafeLog+value.UserMessage).Contains(PrivateMarker));return Task.CompletedTask;});
await WireTest("wrong state produces no token request",()=>{var s=Session();try{s.Complete(new Uri(s.Redirect+"?code=synthetic&state=wrong"));throw new Exception("Expected validation failure");}catch(YouTubeApiException e){Check(e.OAuth.Code==YouTubeOAuthCode.StateMismatch);}return Task.CompletedTask;});
await WireTest("replayed authorization callback remains rejected",()=>{var s=Session();var q=DecodeForm(s.AuthorizationUri.Query);var callback=new Uri(s.Redirect+"?code=synthetic&state="+q["state"]);s.Complete(callback);try{s.Complete(callback);throw new Exception("Expected replay rejection");}catch(YouTubeApiException e){Check(e.OAuth.Code==YouTubeOAuthCode.InvalidCallback);}return Task.CompletedTask;});
if(wireFailures>0)throw new Exception("OAuth wire audit failed: "+wireFailures);
}
}
